package com.personal.assistant.module.dashboard.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.dashboard.dto.DailyDashboardResponse;import com.personal.assistant.module.dashboard.mapper.DailyDashboardMapper;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/dashboard")public class DailyDashboardController{private final DailyDashboardMapper mapper;public DailyDashboardController(DailyDashboardMapper mapper){this.mapper=mapper;}@GetMapping("/daily")public ApiResponse<DailyDashboardResponse>daily(){return ApiResponse.success(mapper.get(SecurityContextHelper.currentUserId()));}}
